query:
SELECT ?site ?statement ?designation ?rank ?start ?end ?pit WHERE {
  ?site wdt:P17 wd:Q155 .
  VALUES ?designation { wd:Q9259 }
  ?site p:P1435 ?statement .
  ?statement ps:P1435 ?designation ; wikibase:rank ?rank .
  FILTER(?rank != wikibase:DeprecatedRank)
  OPTIONAL { ?statement pq:P580 ?start }
  OPTIONAL { ?statement pq:P582 ?end }
  OPTIONAL { ?statement pq:P585 ?pit }
}
